fn solve(s: Vec<char>) -> Vec<char> {
    // Preallocate a vector of the right size: input length + 1 for newline
    let mut result = Vec::with_capacity(s.len() + 1);

    // Replace commas with spaces, keep other characters unchanged
    for c in s {
        if c == ',' {
            result.push(' ');
        } else {
            result.push(c);
        }
    }

    // Append the newline at the end
    result.push('\n');

    result
}

